describe('Account Lockout After Failed Login Attempts', () => {
  const testUser = {
    email: 'testuser@example.com',
    password: 'correctPassword123',
    incorrectPassword: 'wrongPassword123'
  };

  const loginUrl = 'http://localhost:3000/login';
  const maxFailedAttempts = 5;

  beforeEach(() => {
    cy.visit(loginUrl);
    cy.clearCookies();
    cy.clearLocalStorage();
  });

  it('should lock account after 5 failed login attempts', () => {
    // Attempt login 5 times with incorrect password
    for (let i = 1; i <= maxFailedAttempts; i++) {
      cy.get('input[name="email"]').clear().type(testUser.email);
      cy.get('input[name="password"]').clear().type(testUser.incorrectPassword);
      cy.get('button[type="submit"]').click();

      if (i < maxFailedAttempts) {
        cy.get('[data-testid="error-message"]').should('contain', 'Invalid credentials');
        cy.get('[data-testid="attempt-counter"]').should('contain', `Attempt ${i} of ${maxFailedAttempts}`);
      }
    }

    // Verify account is locked after 5th failed attempt
    cy.get('[data-testid="error-message"]').should('contain', 'Account locked');
    cy.get('[data-testid="locked-account-notice"]').should('be.visible');
    cy.get('button[type="submit"]').should('be.disabled');
  });

  it('should prevent login with correct password when account is locked', () => {
    // Lock the account by making 5 failed attempts
    for (let i = 1; i <= maxFailedAttempts; i++) {
      cy.get('input[name="email"]').clear().type(testUser.email);
      cy.get('input[name="password"]').clear().type(testUser.incorrectPassword);
      cy.get('button[type="submit"]').click();
    }

    // Verify account is locked
    cy.get('[data-testid="error-message"]').should('contain', 'Account locked');

    // Attempt login with correct password
    cy.get('input[name="email"]').clear().type(testUser.email);
    cy.get('input[name="password"]').clear().type(testUser.password);
    cy.get('button[type="submit"]').should('be.disabled');

    // Verify still locked and cannot proceed
    cy.get('[data-testid="locked-account-notice"]').should('be.visible');
    cy.get('[data-testid="unlock-instructions"]').should('contain', 'contact support');
  });

  it('should allow login after account unlock via admin action', () => {
    // Lock the account
    for (let i = 1; i <= maxFailedAttempts; i++) {
      cy.get('input[name="email"]').clear().type(testUser.email);
      cy.get('input[name="password"]').clear().type(testUser.incorrectPassword);
      cy.get('button[type="submit"]').click();
    }

    // Admin unlocks the account via API
    cy.request({
      method: 'POST',
      url: 'http://localhost:3000/api/admin/unlock-account',
      headers: {
        'Authorization': 'Bearer admin-token-123'
      },
      body: {
        email: testUser.email
      }
    }).then((response) => {
      expect(response.status).to.equal(200);
    });

    // Refresh and attempt login with correct password
    cy.reload();
    cy.get('input[name="email"]').clear().type(testUser.email);
    cy.get('input[name="password"]').clear().type(testUser.password);
    cy.get('button[type="submit"]').click();

    // Verify successful login
    cy.url().should('include', '/dashboard');
    cy.get('[data-testid="welcome-message"]').should('contain', 'Welcome');
  });

  it('should reset failed attempt counter on successful login', () => {
    // Make 3 failed attempts
    for (let i = 1; i <= 3; i++) {
      cy.get('input[name="email"]').clear().type(testUser.email);
      cy.get('input[name="password"]').clear().type(testUser.incorrectPassword);
      cy.get('button[type="submit"]').click();
    }

    cy.get('[data-testid="attempt-counter"]').should('contain', 'Attempt 3 of 5');

    // Login with correct password
    cy.get('input[name="email"]').clear().type(testUser.email);
    cy.get('input[name="password"]').clear().type(testUser.password);
    cy.get('button[type="submit"]').click();

    // Verify successful login
    cy.url().should('include', '/dashboard');

    // Logout and verify counter is reset
    cy.get('[data-testid="logout-button"]').click();
    cy.visit(loginUrl);

    // Make 1 failed attempt and verify counter shows 1 of 5
    cy.get('input[name="email"]').clear().type(testUser.email);
    cy.get('input[name="password"]').clear().type(testUser.incorrectPassword);
    cy.get('button[type="submit"]').click();

    cy.get('[data-testid="attempt-counter"]').should('contain', 'Attempt 1 of 5');
  });
});
